  "Greeting_BirthDayContent": {"ko":"2005년 9월 30일","en":"September 30, 2005","ja":"2005年9月30日","zh":"2005年9月30日","vi":"Ngày 30 tháng 9 năm 2005","th":"30 กันยายน 2005","ru":"30 сентября 2005 г.","id":"30 September 2005"},
  "Greeting_HomeTown": {"ko":"출신","en":"Home","ja":"出身地","zh":"出生地","vi":"Xuất thân","th":"ถิ่นกำเนิด","ru":"Родной город","id":"Asal"},
  "Greeting_HomeTownContent": {"ko":"서울 종로구 인사동","en":"Insadong, Seoul","ja":"ソウル特別市 鍾路区 仁寺洞","zh":"首尔市钟路区仁寺洞","vi":"Insadong, Jongno-gu, Seoul","th":"อินซาดง เขตจงโน โซล","ru":"Инсадон, Сеул","id":"Insadong, Jongno-gu, Seoul"},
  "Greeting_Nationality": {"ko":"국적","en":"Nationality","ja":"国籍","zh":"国籍","vi":"Quốc tịch","th":"สัญชาติ","ru":"Гражданство","id":"Kewarganegaraan"},
  "Greeting_NationalityContent": {"ko":"대한민국","en":"Republic of Korea","ja":"大韓民国","zh":"大韩民国","vi":"Hàn Quốc","th":"สาธารณรัฐเกาหลี","ru":"Республика Корея","id":"Republik Korea"},
  "Greeting_BloodType": {"ko":"혈액형","en":"Blood","ja":"血液型","zh":"血型","vi":"Nhóm máu","th":"กรุ๊ปเลือด","ru":"Группа крови","id":"Golongan Darah"},
  "Greeting_BloodTypeContent": {"ko":"A형","en":"Type A","ja":"A型","zh":"A型","vi":"Nhóm máu A","th":"กรุ๊ป A","ru":"Группа A","id":"Golongan A"},
  "Greeting_MBTI": {"ko":"MBTI","en":"MBTI","ja":"MBTI","zh":"MBTI","vi":"MBTI","th":"MBTI","ru":"MBTI","id":"MBTI"},
